export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const db = getDb();
  const row = db
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  if (row) return toOrganization(row);

  const hold = db
    .select()
    .from(organizationSlugHolds)
    .where(eq(organizationSlugHolds.slug, slug))
    .get();
  if (!hold || !holdStillActive(hold.retiredAt, new Date())) return null;

  const owner = db
    .select()
    .from(organizations)
    .where(and(eq(organizations.id, hold.orgId), isNull(organizations.archivedAt)))
    .get();
  return owner ? toOrganization(owner) : null;
}

