/**
 * Replaces `from` with `to` and retires `from`. A slug the same workspace
 * retired is reclaimed (that hold ends). Any other live hold, and any other
 * workspace's current slug — archived or not — is refused.
 */
export async function renameOrgSlug(
  orgId: OrgId,
  from: string,
  to: string,
  retiredAt: IsoTimestamp,
): Promise<Organization> {
  const now = new Date(retiredAt);
  const db = getDb();

  const row = db.transaction((tx) => {
    const currentOwner = tx
      .select()
      .from(organizations)
      .where(eq(organizations.slug, to))
      .get();
    if (currentOwner && currentOwner.id !== orgId) {
      throw new InvalidSlugError(to, "is not available");
    }

    const targetHolds = tx
      .select()
      .from(organizationSlugHolds)
      .where(eq(organizationSlugHolds.slug, to))
      .all();

    for (const hold of targetHolds) {
      const own = hold.orgId === orgId;
      if (!own && holdStillActive(hold.retiredAt, now)) {
        throw new InvalidSlugError(to, "is not available");
      }
      tx.delete(organizationSlugHolds)
        .where(eq(organizationSlugHolds.id, hold.id))
        .run();
    }

    const previousHolds = tx
      .select()
      .from(organizationSlugHolds)
      .where(eq(organizationSlugHolds.slug, from))
      .all();
    for (const hold of previousHolds) {
      tx.delete(organizationSlugHolds)
        .where(eq(organizationSlugHolds.id, hold.id))
        .run();
    }

    tx.insert(organizationSlugHolds)
      .values({
        id: newId(),
        orgId,
        slug: from,
        retiredAt,
      })
      .run();

    const updated = tx
      .update(organizations)
      .set({ slug: to, updatedAt: retiredAt })
      .where(eq(organizations.id, orgId))
      .returning()
      .get();

    if (!updated) throw new Error(`Organization ${orgId} not found`);
    return updated;
  });

  return toOrganization(row);
}

/** Feeds `uniqueSlug()`; matching on the prefix keeps the scan small. */
export async function listTakenOrgSlugs(
  prefix: string,
): Promise<readonly string[]> {
  const db = getDb();
  const now = new Date();
  const rows = db
    .select({ slug: organizations.slug })
    .from(organizations)
    .where(like(organizations.slug, `${prefix}%`))
    .all();

  const held = db
    .select({
      slug: organizationSlugHolds.slug,
      retiredAt: organizationSlugHolds.retiredAt,
    })
    .from(organizationSlugHolds)
    .where(like(organizationSlugHolds.slug, `${prefix}%`))
    .all();

  const slugs = new Set<string>();
  for (const row of rows) slugs.add(row.slug);
  for (const row of held) {
    if (holdStillActive(row.retiredAt, now)) slugs.add(row.slug);
  }
  return [...slugs];
}

type HoldExecutor = Pick<ReturnType<typeof getDb>, "select" | "delete">;

/** Drops an expired hold so the slug can be stored as current again. */
function releaseExpiredHold(db: HoldExecutor, slug: string, now: Date): void {
  const holds = db
    .select()
    .from(organizationSlugHolds)
    .where(eq(organizationSlugHolds.slug, slug))
    .all();

  for (const hold of holds) {
    if (!holdStillActive(hold.retiredAt, now)) {
      db.delete(organizationSlugHolds)
        .where(eq(organizationSlugHolds.id, hold.id))
        .run();
    }
  }
}

