/**
 * Changes the workspace URL to the exact slug the caller typed. The previous
 * slug is retired for `ORG_SLUG_HOLD_DAYS`; renaming to the slug already in
 * use changes nothing and publishes nothing.
 */
export async function renameOrganizationSlug(
  actor: Actor,
  input: RenameOrganizationSlugInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:update", orgResource(input.orgId));

  const current = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (input.slug === current.slug) {
    return current;
  }

  assertValidSlug(input.slug);

  const occurredAt = toIsoTimestamp(new Date());
  const updated = await orgRepo.renameOrgSlug(
    input.orgId,
    current.slug,
    input.slug,
    occurredAt,
  );

  await emit("organization.slug_changed", {
    orgId: updated.id,
    actorId: actor.userId,
    occurredAt,
    from: current.slug,
    to: updated.slug,
  });

  await record(updated.id, "organization.slug_changed", {
    actorId: actor.userId,
    subjectKind: "organization",
    subjectId: updated.id,
    projectId: null,
    summary: `Slug ${current.slug} → ${updated.slug}`,
    metadata: { from: current.slug, to: updated.slug },
  });

  return updated;
}

