import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
import { ORG_SLUG_HOLD_DAYS } from "@/config/constants";
import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { InvalidSlugError } from "@/lib/slug";
import { activityFilterSchema } from "@/schemas/activity";
import { renameOrganizationSlugSchema } from "@/schemas/organization";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { resolveActorForOrg } from "@/server/services/session-service";
import {
  createOrganization,
  getOrganizationSummary,
  listOrganizationsForUser,
  renameOrganizationSlug,
  resolveOrgBySlug,
} from "@/server/services/organization-service";
import { toIsoTimestamp } from "@/types/common";
import type { SessionPrincipal } from "@/types/member";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

const DAY_MS = 24 * 60 * 60 * 1000;

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("acme");
  other = await createTenant("globex");
});

afterAll(() => {
  vi.useRealTimers();
  cleanup();
});

function principalFor(source: Tenant): SessionPrincipal {
  return {
    userId: source.userIds.admin,
    email: "admin@acme.test",
    activeOrgId: source.org.id,
    expiresAt: toIsoTimestamp(new Date(Date.now() + DAY_MS)),
  };
}

describe("renameOrganizationSlug", () => {
  it("accepts the schema and the audit filter", () => {
    expect(ORG_SLUG_HOLD_DAYS).toBe(30);
    const parsed = renameOrganizationSlugSchema.parse({
      orgId: tenant.org.id,
      slug: "acme-renamed",
    });
    expect(parsed.slug).toBe("acme-renamed");
    expect(
      activityFilterSchema.safeParse({
        orgId: tenant.org.id,
        action: ["organization.slug_changed"],
        limit: 25,
        cursor: null,
      }).success,
    ).toBe(true);
  });

  it("renames, publishes once, audits once, and keeps the old slug", async () => {
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(new Date("2026-04-01T00:00:00.000Z"));

    const seen: { from: string; to: string; actorId: string | null }[] = [];
    const off = subscribe("organization.slug_changed", (payload) => {
      seen.push(payload);
    });

    const before = await orgRepo.findOrgById(tenant.org.id);
    const updated = await renameOrganizationSlug(tenant.actors.admin, {
      orgId: tenant.org.id,
      slug: "acme-renamed",
    });

    expect(updated.slug).toBe("acme-renamed");
    expect(updated.name).toBe(before?.name);
    expect(updated.plan).toBe(before?.plan);
    expect(updated.ownerId).toBe(before?.ownerId);
    expect(updated.settings).toEqual(before?.settings);
    expect(updated.logoUrl).toBe(before?.logoUrl);
    expect(updated.createdAt).toBe(before?.createdAt);

    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.admin,
      from: "acme",
      to: "acme-renamed",
      occurredAt: "2026-04-01T00:00:00.000Z",
    });

    const audit = await activityRepo.listActivity({
      orgId: tenant.org.id,
      action: ["organization.slug_changed"],
      limit: 25,
      cursor: null,
    });
    expect(audit.items).toHaveLength(1);
    expect(audit.items[0]).toMatchObject({
      action: "organization.slug_changed",
      actorId: tenant.userIds.admin,
      subjectKind: "organization",
      subjectId: tenant.org.id,
      metadata: { from: "acme", to: "acme-renamed" },
    });

    const viaOld = await resolveOrgBySlug("acme");
    expect(viaOld?.id).toBe(tenant.org.id);
    expect(viaOld?.slug).toBe("acme-renamed");

    const summary = await getOrganizationSummary(tenant.actors.admin, tenant.org.id);
    expect(summary.organization.slug).toBe("acme-renamed");

    const listed = await listOrganizationsForUser(tenant.userIds.admin);
    expect(listed.find((org) => org.id === tenant.org.id)?.slug).toBe("acme-renamed");

    const actor = await resolveActorForOrg(principalFor(tenant), "acme");
    expect(actor?.orgId).toBe(tenant.org.id);
    const actorNew = await resolveActorForOrg(principalFor(tenant), "acme-renamed");
    expect(actorNew?.orgId).toBe(tenant.org.id);

    off();
    vi.useRealTimers();
  });

  it("is a no-op when the slug does not change", async () => {
    const seen: unknown[] = [];
    const off = subscribe("organization.slug_changed", (payload) => {
      seen.push(payload);
    });
    const before = await orgRepo.findOrgById(tenant.org.id);
    const again = await renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: "acme-renamed",
    });
    expect(again).toEqual(before);
    expect(seen).toHaveLength(0);
    const audit = await activityRepo.listActivity({
      orgId: tenant.org.id,
      action: ["organization.slug_changed"],
      limit: 25,
      cursor: null,
    });
    expect(audit.items).toHaveLength(1);
    off();
  });

  it("refuses a bad slug, a reserved slug, and a slug someone else holds", async () => {
    const before = await orgRepo.findOrgById(tenant.org.id);
    await expect(
      renameOrganizationSlug(tenant.actors.admin, {
        orgId: tenant.org.id,
        slug: "Acme",
      }),
    ).rejects.toBeInstanceOf(InvalidSlugError);
    await expect(
      renameOrganizationSlug(tenant.actors.admin, {
        orgId: tenant.org.id,
        slug: "billing",
      }),
    ).rejects.toBeInstanceOf(InvalidSlugError);
    await expect(
      renameOrganizationSlug(tenant.actors.admin, {
        orgId: tenant.org.id,
